package dev.cosmerearcanists.equipment;
import dev.cosmerearcanists.hemalurgy.*;
import java.util.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.*;
public final class SpikeItem extends Item {
    public final String metal;
    public SpikeItem(String metal){super(new Properties());this.metal=metal;}
    @Override public boolean isFoil(ItemStack stack){return HemalurgicSpikes.marked(stack)||super.isFoil(stack);}
    @Override public void appendHoverText(ItemStack stack,TooltipContext context,List<Component> lines,TooltipFlag flag){var charge=HemalurgicSpikes.contents(stack);if(charge!=null){lines.add(Component.literal("Charged: "+HemalurgicSpikes.label(charge)));if(charge.connection()!=null){lines.add(Component.literal("Stored player Connections: "+charge.connection().players().size()));lines.add(Component.literal("Home world: "+(charge.connection().homeWorld().isEmpty()?"none":charge.connection().homeWorld())));lines.add(Component.literal("Donor Identity: "+charge.connection().identity()));}else if(charge.cognition().resistance()>0){lines.add(Component.literal(String.format(Locale.ROOT,"Emotional Allomancy resistance: %.2f%%",100*charge.cognition().resistance())));if(charge.cognition().memoryCapacity()>0)lines.add(Component.literal(String.format(Locale.ROOT,"Feruchemical copper capacity: +%.2f%%",100*charge.cognition().memoryCapacity())));}else if(charge.power().equals(HemalurgicTraits.SENSES)){var s=charge.senses();lines.add(Component.literal(String.format(Locale.ROOT,"Sight +%.2f%% · hearing +%.2f%% · touch +%.2f%%",100*s.sight(),100*s.hearing(),100*s.touch())));}else lines.add(Component.literal(String.format(Locale.ROOT,charge.power().equals(HemalurgicTraits.STRENGTH)?"Stored attack damage: +%.3f":"Stored power strength: %.3f",charge.strength())));var view=stack.getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getCompound(ImplantService.DISPLAY);lines.add(Component.literal(view.isEmpty()?"Source Identity preserved · not implanted.":String.format(Locale.ROOT,"Implanted · effectiveness %.0f%%",100*view.getDouble("accuracy"))));lines.add(Component.literal("Charged spikes cannot be fired or crafted."));}else if(HemalurgicSpikes.marked(stack))lines.add(Component.literal("Unrecognized charged contents · preserved."));else{lines.add(Component.literal("Theft: "+HemalurgyRules.description(metal)));if(metal.equals("aluminum"))lines.add(Component.literal("Killing melee hit: player power suppression, no stolen charge."));else if(metal.equals("duralumin"))lines.add(Component.literal("Killing melee hit: steal a player's Connections and Identity."));else if(metal.equals("iron")||metal.equals("tin")||metal.equals("zinc")||metal.equals("copper"))lines.add(Component.literal("Deliver the killing melee hit to store the victim's natural trait."));else if(HemalurgyRules.POWERS.containsKey(metal))lines.add(Component.literal("Deliver the killing melee hit to steal the strongest eligible power."));}}
}
